import{H as e,_t as t,nt as n,rt as r}from"./chunks/framework.ByJSXnli.js";var i=JSON.parse(`{"title":"Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/requirements.md","filePath":"contributing/requirements.md"}`),a={name:`contributing/requirements.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h1><p>This page records the high level capability baseline for HeuristicLib. It states what the library must support without defining the architecture or repeating individual system contracts.</p><p>Use the <a href="/reference/glossary.html">Glossary</a> for terminology, <a href="/guide/">Introduction</a> for the public model and the focused topic pages for detailed behavior.</p><h2 id="purpose-and-scope" tabindex="-1">Purpose and scope <a class="header-anchor" href="#purpose-and-scope" aria-label="Permalink to “Purpose and scope”">​</a></h2><ul><li>HeuristicLib must be a customizable optimization library rather than a fixed collection of solvers.</li><li>Users must be able to define problems, candidate representations, algorithms, operators and analyses.</li><li>Common algorithms should offer a short setup path while advanced users retain deep customization.</li><li>The library must support heuristic optimization beyond evolutionary algorithms.</li><li>Domain workflows may validate and extend the general model but must not define it.</li><li>Native C# is the primary API while Python and other integrations use the same library model.</li></ul><h2 id="functional-requirements" tabindex="-1">Functional requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to “Functional requirements”">​</a></h2><h3 id="problems-and-representations" tabindex="-1">Problems and representations <a class="header-anchor" href="#problems-and-representations" aria-label="Permalink to “Problems and representations”">​</a></h3><ul><li>Support built in and user defined candidate representations.</li><li>Support single objective and multi objective optimization.</li><li>Support constrained, deterministic, stochastic, noisy and dynamic problems.</li><li>Support mixed and composite representations.</li><li>Allow domain specific workflows and large data backed problems without making them core concepts.</li></ul><h3 id="algorithms-and-composition" tabindex="-1">Algorithms and composition <a class="header-anchor" href="#algorithms-and-composition" aria-label="Permalink to “Algorithms and composition”">​</a></h3><ul><li>Support population based and single solution algorithms.</li><li>Support evolutionary, local search, construction, hybrid and meta optimization workflows.</li><li>Support reusable typed operators and problem specific extensions.</li><li>Support algorithm and operator composition where the combined semantics are clear.</li><li>Support multi population and layered workflows.</li><li>Preserve static compatibility between candidates, search spaces, problems, algorithms and operators where practical.</li><li>Treat evaluator output as the objective vectors of the candidates it received, so caching, retry and dynamic problem behavior can be expressed without mutating input candidates. Candidates change only through explicit operators such as refiners.</li></ul><h3 id="execution" tabindex="-1">Execution <a class="header-anchor" href="#execution" aria-label="Permalink to “Execution”">​</a></h3><ul><li>Support streaming progress and convenient completion.</li><li>Keep randomness, cancellation and other behavior affecting inputs explicit.</li><li>Support deterministic repeated execution.</li><li>Support sequential and concurrent execution where appropriate.</li><li>Preserve logical identity and reproducibility independently of concurrent scheduling.</li><li>Allow reusable configurations to produce independent executions.</li></ul><h3 id="analysis-and-experimentation" tabindex="-1">Analysis and experimentation <a class="header-anchor" href="#analysis-and-experimentation" aria-label="Permalink to “Analysis and experimentation”">​</a></h3><ul><li>Support reusable analysis with typed results.</li><li>Allow analysis across operator activity and algorithm progress without changing optimization outcomes.</li><li>Keep analysis valid for nested and composed execution.</li><li>Support experiments over algorithm configurations and parameters.</li><li>Support independent repeated trials for statistical analysis.</li><li>Support sequential and concurrent trial execution.</li><li>Preserve successful trial results when other independent trials fail.</li></ul><h3 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to “Integration”">​</a></h3><ul><li>Support embedding in applications, services and notebooks.</li><li>Provide clean integration boundaries for Python and external evaluation systems.</li><li>Keep the design open to specialized execution backends where they provide concrete value.</li></ul><h2 id="quality-requirements" tabindex="-1">Quality requirements <a class="header-anchor" href="#quality-requirements" aria-label="Permalink to “Quality requirements”">​</a></h2><ul><li>Favor clear, statically typed APIs that are easy to use correctly.</li><li>Keep the conceptual model small and explainable.</li><li>Avoid requiring ordinary users to understand internal execution infrastructure.</li><li>Keep important costs, defaults and side effects visible.</li><li>Keep configurations reusable and execution behavior testable.</li><li>Prefer deterministic behavior and explicit policy over ambient state.</li><li>Keep observability lightweight.</li><li>Maintain documentation and executable API examples for intended public usage.</li></ul><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to “Non-goals”">​</a></h2><ul><li>GUI integration is not part of the core model.</li><li>Backward compatibility does not drive the current alpha API.</li><li>Current package, assembly, namespace and folder boundaries do not define the intended architecture.</li><li>One domain workflow must not dictate the general object model.</li><li>Existing abstractions are not retained solely because they already exist.</li><li>Heavy runtime machinery, hidden orchestration and opaque indirection require concrete justification.</li><li>Convenience APIs and authoring helpers do not define the conceptual core.</li></ul><h2 id="validation-expectations" tabindex="-1">Validation expectations <a class="header-anchor" href="#validation-expectations" aria-label="Permalink to “Validation expectations”">​</a></h2><p>The requirements should be validated through representative workflows rather than isolated type inventories. Those workflows should cover:</p><ul><li>custom typed problems and operators</li><li>standard single objective and multi objective algorithms</li><li>local search and population based execution</li><li>dynamic, noisy and expensive evaluation</li><li>composition and concurrent execution</li><li>run scoped analysis</li><li>grids and repeated experiments</li><li>domain workflows such as symbolic regression</li><li>external language and evaluation integration</li></ul>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};